#!/usr/bin/env node
/**
 * Emit Rust vault-walk policy constants from @collector/shared (#390).
 *
 * Usage:
 *   node scripts/generate-vault-walk-policy.mjs          # write generated file
 *   node scripts/generate-vault-walk-policy.mjs --check  # fail if stale
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const outPath = join(root, "src-tauri/src/generated/vault_walk_policy.rs");
const sharedDist = join(root, "packages/shared/dist/index.js");

const checkOnly = process.argv.includes("--check");

async function loadShared() {
  let mod;
  try {
    mod = await import(pathToFileURL(sharedDist).href);
  } catch (error) {
    console.error(
      "generate-vault-walk-policy: failed to import @collector/shared dist.",
      "Run: npm run build --workspace @collector/shared",
    );
    throw error;
  }
  const names = mod.RESERVED_VAULT_ENTRY_NAMES;
  const suffix = mod.ITEM_MEDIA_SUFFIX;
  if (!Array.isArray(names) || names.length === 0) {
    throw new Error("RESERVED_VAULT_ENTRY_NAMES missing or empty");
  }
  if (typeof suffix !== "string" || suffix.length === 0) {
    throw new Error("ITEM_MEDIA_SUFFIX missing or empty");
  }
  return { names: [...names], suffix };
}

function renderRust({ names, suffix }) {
  const entries = names
    .map((name) => `    "${name.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}",`)
    .join("\n");
  const escapedSuffix = suffix.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  return `// @generated by scripts/generate-vault-walk-policy.mjs — do not edit by hand.
// Source of truth: packages/shared/src/constants.ts (#390).
// Regenerate: npm run generate:vault-walk-policy

/// Sidecar dir next to \`note.md\` → \`note.media/\`.
pub const ITEM_MEDIA_SUFFIX: &str = "${escapedSuffix}";

/// Top-level names that are never markdown items / real folders.
pub const RESERVED_VAULT_ENTRIES: &[&str] = &[
${entries}
];
`;
}

const policy = await loadShared();
const next = renderRust(policy);

mkdirSync(dirname(outPath), { recursive: true });

if (checkOnly) {
  let current = "";
  try {
    current = readFileSync(outPath, "utf8");
  } catch {
    console.error(`check:vault-walk-policy: missing ${outPath}`);
    console.error("Run: npm run generate:vault-walk-policy");
    process.exit(1);
  }
  if (current !== next) {
    console.error(
      "check:vault-walk-policy: generated file is stale vs @collector/shared.",
    );
    console.error("Run: npm run generate:vault-walk-policy");
    process.exit(1);
  }
  console.log("check:vault-walk-policy: OK");
  process.exit(0);
}

writeFileSync(outPath, next, "utf8");
console.log(`wrote ${outPath}`);
